CustomField.formula:
IF((
ROUND( 8 * ( ( 5 * FLOOR( ( DATEVALUE( Case_First_Accepted_Date__c ) - DATE( 1900, 1, 8) ) / 7) + MIN(5, MOD( DATEVALUE( Case_First_Accepted_Date__c) - DATE( 1900, 1, 8), 7) + MIN( 1, 24 / 8 * ( MOD( Case_First_Accepted_Date__c - DATETIMEVALUE( '1900-01-08 12:00:00' ), 1 ) ) ) ) ) - ( 5 * FLOOR( ( DATEVALUE( CreatedDate ) - DATE( 1900, 1, 8) ) / 7) + MIN( 5, MOD( DATEVALUE( CreatedDate ) - DATE( 1996, 1, 1), 7 ) + MIN( 1, 24 / 8 * ( MOD( CreatedDate - DATETIMEVALUE( '1900-01-08 12:00:00' ), 1) ) ) ) ) ), 0 )
)<0,0, ROUND( 8 * ( ( 5 * FLOOR( ( DATEVALUE( Case_First_Accepted_Date__c ) - DATE( 1900, 1, 8) ) / 7) + MIN(5, MOD( DATEVALUE( Case_First_Accepted_Date__c) - DATE( 1900, 1, 8), 7) + MIN( 1, 24 / 8 * ( MOD( Case_First_Accepted_Date__c - DATETIMEVALUE( '1900-01-08 12:00:00' ), 1 ) ) ) ) ) - ( 5 * FLOOR( ( DATEVALUE( CreatedDate ) - DATE( 1900, 1, 8) ) / 7) + MIN( 5, MOD( DATEVALUE( CreatedDate ) - DATE( 1996, 1, 1), 7 ) + MIN( 1, 24 / 8 * ( MOD( CreatedDate - DATETIMEVALUE( '1900-01-08 12:00:00' ), 1) ) ) ) ) ), 0 ))
